// 原oracle切片驱动真实C域规则；分项等价不替代中央完整半日验收。
#include "background_support.hpp"
#include "resident/domains/interaction/interaction_access.hpp"
// 绑定同候选实际共同记录与C域，避免测试夹具静默旁路忙碌或伤势守卫。
struct AccessFixture {
    InteractionAccess access;MilitaryAccess military;
    AccessFixture(CommonStore& c,InteractionState& s,const InteractionCatalog& cat,const CommonCatalog& common){
        access.resolve_location=[&c](const StableId& id){return checked(c.resolved_location(id));};access.role=[&c](const StableId& id)->std::optional<RoleAssignmentView>{auto r=c.state().roles.find(id);if(!r)return {};return RoleAssignmentView{r->actor_id,r->enabled};};access.battle_occupied=[](auto&){return false;};access.task_status=[&s](const StableId& actor,const StableId& offer){for(auto& knowledge:s.knowledge)if(knowledge.actor_id==actor)for(auto& k:knowledge.offers)if(k.offer_id==offer)return StableId("known");return StableId("unknown");};military.interaction=&s;military.interaction_catalog=&cat;military.interaction_access=&access;military.actor_injury=[&c](auto& id){return c.state().actors.find(id)->injury;};military.item_weight=[&common](auto& id){return common.items.find(id)->weight;};military.in_party=[&c](auto& id){for(auto& party:c.state().parties.rows())if(std::find(party.second.members.begin(),party.second.members.end(),id)!=party.second.members.end())return true;return false;};
    }
};
int main(int argc,char** argv){assert(argc==2);std::string root=argv[1];auto index=read_file(root+"/oracle-index.json");auto catalog=read_file(root+"/expanded-catalog.json");auto common=std::make_shared<const CommonCatalog>(checked(decode_common_catalog(*catalog.find("data"))));auto mcat=checked(decode_military_catalog(*catalog.find("data"),boundary::get_string(read_file(root+"/"+boundary::get_string(*index.find("initial_state"),"file","initial")),"scenario_id","state")));auto icat=checked(decode_interaction_catalog(*catalog.find("data"),common));auto& commands=*index.find("commands")->as<BoundaryValue::Array>();auto boundary=[&](int n){return read_file(root+"/"+boundary::get_string(*commands[n].find("after"),"file","file"));};
    // 正式报价与GD真实NPC调用逐字段/类型/键序对照，包含params及军粮续航provisions。
    auto observed_offer=[&](int command_index,const StableId& kind,const StableId& actor){auto diagnostic=read_file(root+"/command-00"+std::to_string(command_index)+".json");for(auto& call:*diagnostic.find("observed_calls")->as<BoundaryValue::Array>()){if(boundary::get_string(call,"entry","call")=="apply"&&boundary::get_string(call,"kind","call")==kind&&boundary::get_string(call,"actor_id","call")==actor)return std::pair<BoundaryValue,BoundaryValue>{*call.find("params"),*call.find("offer")};}std::abort();};
    for(auto entry:std::vector<std::tuple<int,int,StableId,StableId>>{{0,1,"office_accept","actor.blackwater.commander"},{3,4,"army_form","actor.blackwater.commander"}}){auto source=boundary(std::get<0>(entry));CommonStore pc(domain_common(source,*common),common);auto pm=checked(decode_military_seed(source));auto pi=checked(decode_interaction_seed(source));AccessFixture pa(pc,pi,icat,*common);auto evidence=observed_offer(std::get<1>(entry),std::get<2>(entry),std::get<3>(entry));auto command=checked(decode_military_command(std::get<2>(entry),evidence.first));auto quote=checked(preview_military(pc,pm,mcat,pa.military,std::get<3>(entry),command));equal(checked(encode_military_quote(quote,command)),evidence.second,"full military quote");}
    // 保留独立审查原始红例：同步改空fact/action货物、只改request钱数都必须在写入前拒绝。
    auto reject_tamper=[&](const std::function<void(BoundaryValue&)>& mutate,const StableId& expected){auto raw=boundary(5);mutate(raw);CommonStore tc(domain_common(raw,*common),common);auto tm=checked(decode_military_seed(raw));auto ti=checked(decode_interaction_seed(raw));AccessFixture ta(tc,ti,icat,*common);auto old_common=encode_common_state(tc.state());auto old_domain=checked(export_military_state(tm));auto valid=validate_military_state(tc,tm,mcat,ta.military);assert(!valid.ok&&valid.error.original.code==expected);auto action=*tc.action("action:2574");action.remaining_ticks=0;auto finished=finish_military_action(tc,tm,mcat,ta.military,action);assert(!finished.ok&&finished.error.original.code==expected);equal(old_common,encode_common_state(tc.state()),"failed finish unchanged common");equal(old_domain,checked(export_military_state(tm)),"failed finish unchanged military");};
    reject_tamper([](auto& raw){for(auto parent:{raw.find("actions")->find("action:2574")->find("params"),raw.find("facts")->find("action:2574")})parent->find("terms")->find("goods")->data=BoundaryValue::Dict{};},"MilitaryEquipmentTermsMismatch");
    reject_tamper([](auto& raw){raw.find("actions")->find("action:2574")->find("params")->find("request")->find("money")->data=Integer{0};},"InvalidMilitarySupplyTerms");
    reject_tamper([](auto& raw){raw.find("wallets")->find("wallet.blackwater.camp")->find("reserved")->find("action:2574")->data=Integer{299};},"MilitaryEscrowMismatch");
    reject_tamper([](auto& raw){for(auto& lot:*raw.find("inventories")->find("inventory.blackwater.camp")->find("lots")->template as<BoundaryValue::Array>())if(boundary::get_string(lot,"reserved_by","lot")=="action:2574"&&boundary::get_string(lot,"item_id","lot")=="item.grain")lot.find("quantity")->data=Integer{799};},"MilitaryEquipmentReservationMismatch");
    {auto raw=boundary(5);raw.find("facts")->find("military:671")->find("organization_id")->data=StableId("org.west");CommonStore tc(domain_common(raw,*common),common);auto tm=checked(decode_military_seed(raw));auto ti=checked(decode_interaction_seed(raw));AccessFixture ta(tc,ti,icat,*common);auto rejected=validate_military_state(tc,tm,mcat,ta.military);assert(!rejected.ok&&rejected.error.original.code=="MilitarySupplyOrganizationMismatch");}
    // 限定profile不接受未注册参数；冷解码/seed均明确capability拒绝，不能导出失败或默默丢值。
    {auto source=boundary(3);CommonStore ec(domain_common(source,*common),common);auto em=checked(decode_military_seed(source));auto ei=checked(decode_interaction_seed(source));AccessFixture ea(ec,ei,icat,*common);auto evidence=observed_offer(4,"army_form","actor.blackwater.commander");for(auto check:std::vector<std::pair<StableId,StableId>>{{"unit_ids","MilitaryCommandScope"},{"retainer_ids","InvalidRetainerRoster"}}){auto bad=evidence.first;auto value=BoundaryValue{BoundaryValue::Array{BoundaryValue{StableId("")}}};if(auto field=bad.find(check.first))*field=value;else bad.as<BoundaryValue::Dict>()->emplace_back(check.first,value);auto command=checked(decode_military_command("army_form",bad));auto quote=preview_military(ec,em,mcat,ea.military,"actor.blackwater.commander",command);assert(!quote.ok&&quote.error.original.code==check.second);}auto extra=evidence.first;extra.as<BoundaryValue::Dict>()->emplace_back("tag",BoundaryValue{StableId("harmless")});auto rejected=decode_military_command("army_form",extra);assert(!rejected.ok&&rejected.error.kind==ErrorKind::unsupported_capability&&rejected.error.phase=="command");auto seed=boundary(5);seed.find("actions")->find("action:2574")->find("params")->find("request")->as<BoundaryValue::Dict>()->emplace_back("tag",BoundaryValue{StableId("harmless")});auto install=decode_military_seed(seed);assert(!install.ok&&install.error.kind==ErrorKind::unsupported_capability&&install.error.phase=="decode");}
    auto before=boundary(1),after=boundary(2);auto military=checked(decode_military_seed(before));auto interaction=checked(decode_interaction_seed(before));CommonStore c(domain_common(before,*common),common);AccessFixture access(c,interaction,icat,*common);auto action=*c.action("action:1490");action.remaining_ticks=0;auto outcome=checked(finish_military_action(c,military,mcat,access.military,action));assert(outcome.success&&outcome.office_id=="office.blackwater.army");auto exported=checked(export_military_state(military));equal(*exported.find("offices")->find("office.blackwater.army"),*after.find("offices")->find("office.blackwater.army"),"office completion");equal(*exported.find("facts")->find("action:1490"),*after.find("facts")->find("action:1490"),"office fact");
    // 明确独立域切片：供粮真实执行；庄务在原链另消费两个ID，夹具取其已观测边界编号后再测组军。
    before=boundary(5);after=boundary(6);military=checked(decode_military_seed(before));interaction=checked(decode_interaction_seed(before));c=CommonStore(domain_common(before,*common),common);AccessFixture form_access(c,interaction,icat,*common);require(military_supply_step(c,military,mcat,form_access.military,4));assert(c.state().next_instance_id==2584);for(auto id:{"military:2582","military:2583"}){auto fragment=checked(export_military_state(military));equal(*fragment.find("facts")->find(id),*after.find("facts")->find(id),"supply fact");}c.state().next_instance_id=2586;action=*c.action("action:2574");action.remaining_ticks=0;auto formed=checked(finish_military_action(c,military,mcat,form_access.military,action));assert(formed.success&&formed.army_id=="army:2586");exported=checked(export_military_state(military));equal(*exported.find("armies")->find("army:2586"),*after.find("armies")->find("army:2586"),"formed army");equal(*exported.find("facts")->find("action:2574"),*after.find("facts")->find("action:2574"),"formation fact");auto common_out=encode_common_state(c.state());equal(*common_out.find("inventories")->find("army_inventory:army:2586"),*after.find("inventories")->find("army_inventory:army:2586"),"army real inventory");equal(*common_out.find("wallets")->find("army_wallet:army:2586"),*after.find("wallets")->find("army_wallet:army:2586"),"army real money");assert(c.state().next_instance_id==2590);auto formed_common=encode_common_state(c.state());auto repeat=checked(finish_military_action(c,military,mcat,form_access.military,action));assert(repeat.already_completed&&*repeat.already_completed&&repeat.army_id=="army:2586");equal(formed_common,encode_common_state(c.state()),"idempotent form completion");
    // 每个会面command直接在其真实before边界驱动C；旅行标记由窄写端口保同一活动行动。
    before=boundary(2);after=boundary(3);military=checked(decode_military_seed(before));interaction=checked(decode_interaction_seed(before));c=CommonStore(domain_common(before,*common),common);AccessFixture leave_access(c,interaction,icat,*common);Integer resumed=0;leave_access.access.set_journey_encounter=[&](const StableId& id,const StableId& encounter,bool paused){assert(c.action(id)&&encounter.empty()&&!paused);++resumed;return common_success();};auto leave=InteractionCommand{EncounterLeave{"encounter:1658"}};auto offer=checked(preview_interaction(c,interaction,icat,leave_access.access,"actor.player",leave));auto left=checked(apply_interaction(c,interaction,icat,leave_access.access,"actor.player",leave,offer));assert(resumed==2&&left.settlement_result=="result:2075");equal(*checked(export_interaction_state(interaction)).find("encounters"),*after.find("encounters"),"encounter leave");
    // 真会面talk→say→choice→say→choice→end，不解绑仍待处理会面，也不改钱包或行动。
    interaction=checked(decode_interaction_seed(before));c=CommonStore(domain_common(before,*common),common);AccessFixture talk_access(c,interaction,icat,*common);auto talk=InteractionCommand{EncounterTalk{"encounter:1658"}};auto q=checked(preview_interaction(c,interaction,icat,talk_access.access,"actor.player",talk));checked(apply_interaction(c,interaction,icat,talk_access.access,"actor.player",talk,q));assert(interaction.interactions.size()==1&&interaction.interactions[0].phase=="say");for(InteractionCommand command:{InteractionCommand{DialogueNext{}},InteractionCommand{DialogueChoose{"ask"}},InteractionCommand{DialogueNext{}},InteractionCommand{DialogueChoose{"leave"}}}){q=checked(preview_interaction(c,interaction,icat,talk_access.access,"actor.player",command));checked(apply_interaction(c,interaction,icat,talk_access.access,"actor.player",command,q));}assert(interaction.interactions.empty()&&pending_encounter(interaction,"actor.player"));
    // 128条resolved裁剪按created_tick及字面ID排序；有玩家的pending不计在128限额。
    interaction=InteractionState{};c.state().next_instance_id=8;Integer callbacks=0;EncounterInstall hit;hit.leaders={"actor.blackwater.bowman","actor.blackwater.rider"};hit.action_ids={"action:one","action:two"};hit.anchors={WildernessLocation{"map.qingchuan","village.east",{500,500}},WildernessLocation{"map.qingchuan","village.east",{500,500}}};hit.apply_motion=[&](const StableId&,bool interactive){assert(!interactive);++callbacks;return common_success();};std::vector<StableId> created;for(int i=0;i<160;++i)created.push_back(checked(install_encounter(c,interaction,"actor.player",hit)));assert(callbacks==160&&interaction.encounters.size()==128);auto expected=created;std::sort(expected.begin(),expected.end());expected.erase(expected.begin(),expected.end()-128);for(auto& e:interaction.encounters)assert(std::find(expected.begin(),expected.end(),e.id)!=expected.end());
    // 同说话人可继续管理，其他对话provider仍占用；证明A读取适配器没有忽略provider。
    interaction.interactions.push_back({});interaction.interactions.back().actor_id="actor.player";interaction.interactions.back().context.provider_actor_id="actor.walker";InteractionActivity activity(military,interaction);assert(activity.in_interaction("actor.walker")&&!activity.in_interaction("actor.walker","actor.player"));
    auto malformed=checked(decode_interaction_command("encounter_leave",BoundaryValue{BoundaryValue::Dict{{"encounter_id",BoundaryValue{true}}}}));auto bad_encounter=preview_interaction(c,interaction,icat,talk_access.access,"actor.player",malformed);assert(!bad_encounter.ok&&bad_encounter.error.original.code=="UnknownEncounter");auto invalid_office=checked(decode_military_command("office_accept",BoundaryValue{BoundaryValue::Dict{}}));auto actor=c.state().actors.find("actor.player");actor->action_id="";auto bad_office=preview_military(c,military,mcat,talk_access.military,"actor.player",invalid_office);assert(!bad_office.ok&&bad_office.error.original.code=="UnknownOffice");actor->hp=0;bad_office=preview_military(c,military,mcat,talk_access.military,"actor.player",invalid_office);assert(!bad_office.ok&&bad_office.error.original.code=="MilitaryActorUnavailable");
    std::cout<<"background_runtime: PASS (office completion, supply, reserved formation+asset receipt, leave, dialogue branch, 160 encounter trim, activity ownership)\n";
}
